# notiz.py – dein erstes kleines Projekt
import sys

def zeige_notizen():
    try:
        with open("notizen.txt", encoding="utf-8") as f:
            print(f.read() or "(leer)")
    except FileNotFoundError:
        print("(noch keine Notizen)")

def notiz_hinzufuegen(text):
    with open("notizen.txt", "a", encoding="utf-8") as f:
        f.write(text + "\n")
    print("Gespeichert!")

if __name__ == "__main__":
    if len(sys.argv) > 1:
        notiz_hinzufuegen(" ".join(sys.argv[1:]))
    else:
        zeige_notizen()
# Aufruf: python3 notiz.py "Meine erste Notiz"

