// main.cpp – dein erstes kleines Projekt
#include <iostream>
#include <fstream>

void zeige_notizen() {
    std::ifstream datei("notizen.txt");
    if (!datei) { std::cout << "(noch keine Notizen)"; return; }
    std::string zeile;
    while (std::getline(datei, zeile))
        std::cout << zeile << std::endl;
}

int main(int argc, char* argv[]) {
    if (argc > 1) {
        std::ofstream datei("notizen.txt", std::ios::app);
        datei << argv[1] << std::endl;
        std::cout << "Gespeichert!" << std::endl;
    } else {
        zeige_notizen();
    }
    return 0;
}
